<?php
/**  * Fix Price Approval Foreign Key Constraints  * This script fixes the foreign key constraint issues  */  session_start();
require_once __DIR__ . '/db_connect.php';  // Check if user is admin
$user = $_SESSION['user'] ?? null;
if (!$user || !in_array(strtolower($user['role'] ?? ''), ['admin', 'administrator', 'manager', 'superadmin', 'developer'])) {  die('Access Denied: Admin/Manager privileges required');
}  $messages = [];
$action = $_GET['action'] ?? '';  if ($action === 'fix') {  try {  // Step 1: Check if pending_price_approvals table exists  $check_table = $pdo->query("SHOW TABLES LIKE 'pending_price_approvals'");  if ($check_table->rowCount() > 0) {  // Step 2: Drop existing foreign key constraints  try {  $pdo->exec("ALTER TABLE pending_price_approvals DROP FOREIGN KEY fk_pending_price_approvals_product");  $messages[] = ['type' => 'success', 'text' => 'Dropped old foreign key constraint'];  } catch (Exception $e) {  $messages[] = ['type' => 'info', 'text' => 'No existing foreign key to drop'];  }  // Step 3: Delete orphaned records (records with invalid product_id)  $stmt = $pdo->query("  DELETE ppa FROM pending_price_approvals ppa  LEFT JOIN inventory_products ip ON ppa.product_id = ip.id  WHERE ip.id IS NULL  ");  $deleted = $stmt->rowCount();  if ($deleted > 0) {  $messages[] = ['type' => 'success', 'text' => "Deleted $deleted orphaned price approval records"];  } else {  $messages[] = ['type' => 'info', 'text' => 'No orphaned records found'];  }  // Step 4: Re-create foreign key with proper settings  try {  $pdo->exec("  ALTER TABLE pending_price_approvals  ADD CONSTRAINT fk_pending_price_approvals_product  FOREIGN KEY (product_id)  REFERENCES inventory_products(id)  ON UPDATE CASCADE  ON DELETE CASCADE  ");  $messages[] = ['type' => 'success', 'text' => 'Created new foreign key constraint with CASCADE'];  } catch (Exception $e) {  $messages[] = ['type' => 'error', 'text' => 'Error creating foreign key: ' . $e->getMessage()];  }  // Step 5: Verify the fix  $orphaned_check = $pdo->query("  SELECT COUNT(*) FROM pending_price_approvals ppa  LEFT JOIN inventory_products ip ON ppa.product_id = ip.id  WHERE ip.id IS NULL  ")->fetchColumn();  if ($orphaned_check == 0) {  $messages[] = ['type' => 'success', 'text' => 'Verification passed: All records have valid product references'];  } else {  $messages[] = ['type' => 'warning', 'text' => "Warning: $orphaned_check records still have invalid product_id"];  }  } else {  $messages[] = ['type' => 'info', 'text' => 'pending_price_approvals table does not exist yet'];  }  // Step 6: Also check fuel_inventory constraints  try {  $check_fuel = $pdo->query("SHOW TABLES LIKE 'fuel_inventory'");  if ($check_fuel->rowCount() > 0) {  // Remove old constraints  try {  $pdo->exec("ALTER TABLE fuel_inventory DROP FOREIGN KEY fuel_inventory_ibfk_1");  } catch (Exception $e) {}  try {  $pdo->exec("ALTER TABLE fuel_inventory DROP FOREIGN KEY fuel_inventory_ibfk_2");  } catch (Exception $e) {}  // Add proper constraints  try {  $pdo->exec("  ALTER TABLE fuel_inventory  ADD CONSTRAINT fk_fuel_inventory_station  FOREIGN KEY (station_id)  REFERENCES stations(id)  ON UPDATE CASCADE  ON DELETE CASCADE  ");  $messages[] = ['type' => 'success', 'text' => 'Fixed fuel_inventory station constraint'];  } catch (Exception $e) {  $messages[] = ['type' => 'info', 'text' => 'Fuel inventory station constraint already exists'];  }  }  } catch (Exception $e) {  $messages[] = ['type' => 'error', 'text' => 'Error fixing fuel_inventory: ' . $e->getMessage()];  }  } catch (Exception $e) {  $messages[] = ['type' => 'error', 'text' => 'Fatal error: ' . $e->getMessage()];  }
}  // Get current status
$status = [];
try {  // Check pending_price_approvals  $stmt = $pdo->query("  SELECT COUNT(*) as total,  SUM(CASE WHEN ip.id IS NULL THEN 1 ELSE 0 END) as orphaned  FROM pending_price_approvals ppa  LEFT JOIN inventory_products ip ON ppa.product_id = ip.id  ");  $result = $stmt->fetch(PDO::FETCH_ASSOC);  $status['pending_approvals_total'] = $result['total'] ?? 0;  $status['pending_approvals_orphaned'] = $result['orphaned'] ?? 0;  // Check constraints  $constraints = $pdo->query("  SELECT CONSTRAINT_NAME, UPDATE_RULE, DELETE_RULE  FROM information_schema.KEY_COLUMN_USAGE  WHERE TABLE_SCHEMA = DATABASE()  AND TABLE_NAME = 'pending_price_approvals'  AND CONSTRAINT_NAME LIKE 'fk_%'  ")->fetchAll(PDO::FETCH_ASSOC);  $status['constraints'] = $constraints;  } catch (Exception $e) {  $status['error'] = $e->getMessage();
}  ?>
