<html>
<head>  <meta charset="UTF-8">  <title>Fix Price Approval Constraints</title>  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">  <style>  * { margin: 0; padding: 0; box-sizing: border-box; }  body {  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);  padding: 40px 20px;  min-height: 100vh;  }  .container {  max-width: 900px;  margin: 0 auto;  background: white;  border-radius: 16px;  padding: 40px;  box-shadow: 0 20px 60px rgba(0,0,0,0.3);  }  h1 {  color: #dc2626;  margin-bottom: 8px;  font-size: 28px;  display: flex;  align-items: center;  gap: 12px;  }  .subtitle {  color: #64748b;  margin-bottom: 32px;  font-size: 14px;  }  .status-grid {  display: grid;  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));  gap: 16px;  margin-bottom: 32px;  }  .status-card {  background: #f8fafc;  border: 1px solid #e2e8f0;  border-radius: 10px;  padding: 20px;  text-align: center;  }  .status-card.error {  border-color: #fecaca;  background: #fef2f2;  }  .status-card.success {  border-color: #bbf7d0;  background: #f0fdf4;  }  .status-label {  font-size: 11px;  font-weight: 700;  color: #64748b;  text-transform: uppercase;  letter-spacing: 0.5px;  margin-bottom: 8px;  }  .status-value {  font-size: 32px;  font-weight: 800;  color: #002F70;  }  .status-value.error {  color: #dc2626;  }  .status-value.success {  color: #16a34a;  }  .btn {  display: inline-flex;  align-items: center;  gap: 8px;  padding: 14px 28px;  background: linear-gradient(135deg, #dc2626, #b91c1c);  color: white;  border: none;  border-radius: 8px;  font-size: 15px;  font-weight: 600;  cursor: pointer;  text-decoration: none;  transition: transform 0.2s;  }  .btn:hover { transform: translateY(-2px); }  .btn-secondary {  background: #e2e8f0;  color: #475569;  }  .messages {  margin-top: 32px;  }  .message {  padding: 14px 18px;  border-radius: 8px;  margin-bottom: 10px;  display: flex;  align-items: center;  gap: 12px;  font-size: 14px;  }  .message.success {  background: #dcfce7;  border-left: 4px solid #16a34a;  color: #15803d;  }  .message.error {  background: #fee2e2;  border-left: 4px solid #dc2626;  color: #b91c1c;  }  .message.info {  background: #dbeafe;  border-left: 4px solid #3b82f6;  color: #1e40af;  }  .message.warning {  background: #fef3c7;  border-left: 4px solid #f59e0b;  color: #b45309;  }  .actions {  display: flex;  gap: 12px;  margin-top: 24px;  }  .constraint-list {  background: #f8fafc;  border: 1px solid #e2e8f0;  border-radius: 8px;  padding: 16px;  margin-top: 24px;  font-size: 13px;  }  .constraint-list h3 {  color: #1e293b;  margin-bottom: 12px;  font-size: 14px;  }  .constraint-item {  padding: 8px;  border-bottom: 1px solid #e2e8f0;  }  .constraint-item:last-child {  border-bottom: none;  }  </style>
</head>
<body>  <div class="container">  <h1><i class="fas fa-wrench"></i> Fix Price Approval Constraints</h1>  <div class="subtitle">Repair foreign key constraint issues in pending_price_approvals table</div>  <div class="status-grid">  <div class="status-card <?= ($status['pending_approvals_orphaned'] ?? 0) > 0 ? 'error' : 'success' ?>">  <div class="status-label">Total Pending Approvals</div>  <div class="status-value"><?= number_format($status['pending_approvals_total'] ?? 0) ?></div>  </div>  <div class="status-card <?= ($status['pending_approvals_orphaned'] ?? 0) > 0 ? 'error' : 'success' ?>">  <div class="status-label">Orphaned Records</div>  <div class="status-value <?= ($status['pending_approvals_orphaned'] ?? 0) > 0 ? 'error' : 'success' ?>">  <?= number_format($status['pending_approvals_orphaned'] ?? 0) ?>  </div>  </div>  </div>  <?php if (!empty($status['constraints'])): ?>  <div class="constraint-list">  <h3>Current Constraints:</h3>  <?php foreach ($status['constraints'] as $constraint): ?>  <div class="constraint-item">  <strong><?= htmlspecialchars($constraint['CONSTRAINT_NAME']) ?></strong><br>  <small>ON UPDATE: <?= htmlspecialchars($constraint['UPDATE_RULE'] ?? 'N/A') ?> |  ON DELETE: <?= htmlspecialchars($constraint['DELETE_RULE'] ?? 'N/A') ?></small>  </div>  <?php endforeach; ?>  </div>  <?php endif; ?>  <?php if (!empty($messages)): ?>  <div class="messages">  <?php foreach ($messages as $msg): ?>  <div class="message <?= $msg['type'] ?>">  <i class="fas fa-<?= $msg['type'] === 'success' ? 'check-circle' : ($msg['type'] === 'error' ? 'times-circle' : ($msg['type'] === 'warning' ? 'exclamation-triangle' : 'info-circle')) ?>"></i>  <span><?= htmlspecialchars($msg['text']) ?></span>  </div>  <?php endforeach; ?>  </div>  <?php endif; ?>  <div class="actions">  <?php if (($status['pending_approvals_orphaned'] ?? 0) > 0 || empty($messages)): ?>  <a href="?action=fix" class="btn">  <i class="fas fa-tools"></i> Fix Constraints Now  </a>  <?php else: ?>  <a href="?" class="btn btn-secondary">  <i class="fas fa-redo"></i> Refresh Status  </a>  <?php endif; ?>  <a href="manager_set_prices.php" class="btn btn-secondary">  <i class="fas fa-arrow-left"></i> Back to Pricing  </a>  </div>  </div>
